import { Injectable, Logger } from '@nestjs/common';
import OpenAI from 'openai';

export interface OpenAIGenerateImageResponse {
  text: string;
  imageUrl?: string;
}

@Injectable()
export class OpenAIService {
  private readonly logger = new Logger(OpenAIService.name);
  private readonly client: OpenAI;
  private readonly model: string;
  private readonly apiKey: string;
  private readonly baseUrl: string;

  constructor() {
    this.model = process.env.MODEL_NAME || 'gemini-2.5-flash-image-preview';
    this.apiKey = process.env.OPENAI_API_KEY!;
    this.baseUrl = process.env.OPENAI_API_BASE_URL!;
    this.client = new OpenAI({
      apiKey: process.env.OPENAI_API_KEY,
      baseURL: process.env.OPENAI_API_BASE_URL,
    });

    this.logger.log(`STUB client initialized with model: ${this.model}`);
  }

  /**
   * Generate image from prompt and input image
   */
  async generateImage( //TODO - make image array and optional
    imageBase64: string,
    prompt: string,
  ): Promise<OpenAIGenerateImageResponse> {
    try {
      this.logger.log('Calling STUB API for image generation...');

        // STUB response
      
      const textResponse = 'hello, tester! This is a stub response.';
      const imageUrlResponse = "data:image/png;base64,";

      this.logger.log('Image generation completed successfully');

      return {
        imageUrl: imageUrlResponse,
        text: textResponse,
      };
    } catch (error) {
      this.logger.error(`OpenAI API error: ${error.message}`);
      throw error;
    }
  }

  /**
   * Generate text-only response
   */
  async generateText(prompt: string): Promise<string> {
    try {
      const response = await this.client.chat.completions.create({
        model: this.model,
        messages: [
          {
            role: 'user',
            content: prompt,
          },
        ],
        max_tokens: 500,
      });

      return response.choices[0]?.message?.content || '';
    } catch (error) {
      this.logger.error(`OpenAI text generation error: ${error.message}`);
      throw error;
    }
  }
}
